def S(n):
    return sum(int(d) for d in str(n))

def is_valid(n):
    for k in range(38):
        if S(n + k) % 11 == 0:
            return False
    return True

candidates = [999981, 459, 291, 110999990, 1999981, 10**10 - 1]
for c in candidates:
    print(f"Checking candidate {c}: {is_valid(c)}")

# Search for smallest n
found_smallest = None
for n in range(1, 1000000):
    if is_valid(n):
        found_smallest = n
        break

print(f"Smallest n found up to 1,000,000: {found_smallest}")

